parameters.jsCode:
const db = $('Load Sync Map & Stuck Leads').first().json;
const opps = $('Get Won Opportunities').first().json.data.opportunities;
const companies = new Map($('Get Twenty Companies').first().json.data.companies.map((c) => [c.id, c]));
const orders = new Map($('Get Mapped Orders').first().json.body.map((o) => [o.id, o]));
const partners = new Map($('Get Mapped Customers').first().json.body.map((p) => [p.id, p]));
const orderMap = db.sync_map.filter((r) => r.entity_type === 'order');
const customerMap = db.sync_map.filter((r) => r.entity_type === 'customer');
const norm = (s) => String(s ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
const eur = (n) => Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2 }) + ' EUR';

const fixRefs = [];
const replays = [];
const issues = [];
const issue = (key, kind, text) => issues.push({ key, kind, text });

for (const opp of opps) {
  const m = orderMap.find((r) => r.crm_id === opp.id);
  if (!m) { replays.push({ opportunityId: opp.id, name: opp.name }); continue; }
  const order = orders.get(m.odoo_id);
  if (!order) { issue('order-missing:' + opp.id, 'order_missing_in_odoo', opp.name + ': Odoo order ' + m.odoo_name + ' (id ' + m.odoo_id + ') no longer exists'); continue; }
  if (order.state === 'cancel') issue('order-cancelled:' + opp.id, 'order_cancelled', opp.name + ': won in Twenty, but Odoo order ' + order.name + ' is cancelled');
  const oppAmount = opp.amount?.amountMicros != null ? opp.amount.amountMicros / 1e6 : null;
  if (oppAmount !== null && Math.abs(oppAmount - order.amount_untaxed) > 0.01) {
    issue('amount:' + opp.id + ':' + oppAmount + ':' + order.amount_untaxed, 'amount_mismatch',
      opp.name + ': Twenty amount ' + eur(oppAmount) + ' vs Odoo ' + order.name + ' net ' + eur(order.amount_untaxed));
  }
  if ((opp.erpOrderRef ?? '') !== order.name) fixRefs.push({ opportunityId: opp.id, name: opp.name, expected: order.name, actual: opp.erpOrderRef || null });
}

const wonIds = new Set(opps.map((o) => o.id));
for (const m of orderMap) {
  if (!wonIds.has(m.crm_id)) issue('not-won:' + m.crm_id, 'opportunity_not_won', 'Odoo order ' + m.odoo_name + ' exists, but its Twenty opportunity is no longer at stage CUSTOMER (or was deleted)');
}

for (const m of customerMap.filter((r) => r.crm_object === 'companies')) {
  const c = companies.get(m.crm_id);
  const p = partners.get(m.odoo_id);
  if (!c) issue('company-missing:' + m.crm_id, 'company_missing_in_crm', 'Odoo customer ' + m.odoo_name + ' (id ' + m.odoo_id + ') has no company in Twenty any more');
  else if (!p) issue('partner-missing:' + m.odoo_id, 'customer_missing_in_odoo', 'Twenty company ' + c.name + ': Odoo customer id ' + m.odoo_id + ' no longer exists');
  else if (norm(c.name) !== norm(p.name)) issue('name:' + m.crm_id + ':' + norm(c.name) + ':' + norm(p.name), 'name_mismatch', 'Customer name differs: Twenty "' + c.name + '" vs Odoo "' + p.name + '"');
}

for (const l of db.stuck_leads) {
  issue('stuck-lead:' + l.id, 'lead_not_synced', 'Lead ' + l.id + ' (' + l.email + ', ' + (l.company || 'no company') + ') was never synced to Twenty (received ' + String(l.created_at).slice(0, 16) + '). Resend it or check WF-01 errors.');
}

return [{ json: {
  fixRefs, replays, issues,
  stats: { opportunitiesWon: opps.length, ordersMapped: orderMap.length, customersMapped: customerMap.length, stuckLeads: db.stuck_leads.length },
} }];

// Same format and signature as Twenty: HMAC_SHA256(secret, timestamp + ":" + body)
const crypto = require('crypto');
return $('Compare Twenty and Odoo').first().json.replays.map((r) => {
  const body = JSON.stringify({
    eventName: 'opportunity.updated',
    objectMetadata: { nameSingular: 'opportunity' },
    record: { id: r.opportunityId, name: r.name, stage: 'CUSTOMER' },
    updatedFields: ['stage'],
    replayedBy: 'WF-06 reconciliation',
  });
  const ts = String(Date.now());
  const sig = crypto.createHmac('sha256', $env.TWENTY_WEBHOOK_SECRET).update(ts + ':' + body).digest('hex');
  return { json: { ...r, body, ts, sig } };
});

// One item per issue, each with a fresh review token. Always returns at least one item
// (a "none" placeholder), so the report below also runs on clean nights.
const crypto = require('crypto');
const issues = $('Compare Twenty and Odoo').first().json.issues;
if (!issues.length) return [{ json: { none: true, key: '', kind: '', text: '', tokenHash: '', token: '' } }];
return issues.map((i) => {
  const token = crypto.randomBytes(24).toString('base64url');
  return { json: { ...i, none: false, token, tokenHash: crypto.createHash('sha256').update(token).digest('hex') } };
});

const cmp = $('Compare Twenty and Odoo').first().json;
const listed = $('List Issues').all().map((i) => i.json);
const saved = $input.all().map((i) => i.json);
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const link = (id, token, d) => $env.WEBHOOK_URL + 'webhook/review-decision?id=' + id + '&token=' + token + '&decision=' + d;

const issues = listed.filter((i) => !i.none).map((i, n) => ({ ...i, reviewId: saved[n]?.review_id, isNew: saved[n]?.is_new }));
const fixed = $('Fix ERP Ref in Twenty').isExecuted ? cmp.fixRefs : [];
const replayed = $('Replay Win to WF-03').isExecuted ? cmp.replays : [];

const section = (title, rows) => rows.length ? '<h4>' + title + '</h4><ul>' + rows.join('') + '</ul>' : '';
const html = [
  '<h3>Abgleich CRM ↔ ERP / CRM ↔ ERP reconciliation</h3>',
  '<p>Checked: ' + cmp.stats.opportunitiesWon + ' won opportunities, ' + cmp.stats.ordersMapped + ' orders, ' +
    cmp.stats.customersMapped + ' customers.</p>',
  !issues.length && !fixed.length && !replayed.length ? '<p>✅ Twenty and Odoo are consistent. / Alles konsistent.</p>' : '',
  section('Automatisch korrigiert / Fixed automatically', [
    ...fixed.map((f) => '<li>' + esc(f.name) + ': ERP Order Ref ' + esc(f.actual ?? '(empty)') + ' → <b>' + esc(f.expected) + '</b></li>'),
    ...replayed.map((r) => '<li>' + esc(r.name) + ': won but no Odoo order. Event replayed to WF-03, order is being created</li>'),
  ]),
  section('Bitte prüfen / Needs attention', issues.map((i) =>
    '<li>' + esc(i.text) + (i.isNew ? ' <i>(new)</i>' : '') + '<br>' +
    '<a href="' + link(i.reviewId, i.token, 'approve') + '">✅ Erledigt / Resolved</a> &nbsp; ' +
    '<a href="' + link(i.reviewId, i.token, 'reject') + '">✖ Ignorieren / Dismiss</a></li>')),
].join('\n');

return [{ json: {
  subject: 'Abgleich CRM↔ERP / Reconciliation: ' + (issues.length ? issues.length + ' issue(s)' : 'OK') +
    (fixed.length + replayed.length ? ', ' + (fixed.length + replayed.length) + ' fixed' : ''),
  html,
  counts: { issues: issues.length, newIssues: issues.filter((i) => i.isNew).length, fixedRefs: fixed.length, replayedWins: replayed.length, ...cmp.stats },
} }];

